      ...(session.findings !== undefined ? { findings: session.findings } : {}),
      ...(session.history !== undefined ? { history: session.history } : {}),
    };

    this.stateManager.saveTaskState(fullState, selectedWorkspace ? [selectedWorkspace] : []);
