        firstStep: step,
        lastStep: step,
        outcome: clip(normalizeOutcomeText(o.text), 240),
      };
      this.insertRepetition(record);
    }
    record.count++;
    record.lastStep = step;
    if (!stateUnknown) addSeen(this.data.seenObservations, key, (n) => (this.data.evicted.observations += n));
