/** Resource budgets that bound an automatically continued turn. Each has its own termination reason. */
export interface ContinuationBudget {
  /** Total steps a turn may run across all segments (STEP_BUDGET_EXHAUSTED). */
  maxTotalSteps: number;
  /** Wall-clock budget of one turn in minutes (TIME_BUDGET_EXHAUSTED). */
  maxTurnMinutes: number;
  /** Consecutive steps without observed progress before the turn stops (STAGNATION_DETECTED). */
  stagnationSteps: number;
  /** Recovery notes the agent may inject for a repeated identical action before stopping (bounded recovery). */
  maxRecoveries: number;
  /** Times the agent may be asked to continue when it stops with acceptance requirements still open. */
  maxCompletionNudges: number;
}

export const DEFAULT_CONTINUATION: ContinuationBudget = {
  maxTotalSteps: 300,
  maxTurnMinutes: 120,
  stagnationSteps: 12,
  maxRecoveries: 2,
  maxCompletionNudges: 2,
};
    ...(cloudRoutedOrigins.length ? { cloudRoutedOrigins } : {}),
    ...(reasoningEffort ? { reasoningEffort } : {}),
    ...(anthropicThinkingBudget ? { anthropicThinkingBudget } : {}),
  };
}

/**
 * Continuation budgets: flags, then NEXUS_MAX_TOTAL_STEPS / NEXUS_MAX_TURN_MINUTES / NEXUS_STAGNATION_STEPS, then
 * defaults. `--no-continuation` (or NEXUS_CONTINUATION=0) restores the single-segment turn that ends at --max-steps.
 */
export function continuationBudget(options: any): ContinuationBudget | undefined {
  if (options.continuation === false || process.env.NEXUS_CONTINUATION === "0") return undefined;
  const positive = (flag: unknown, env: string | undefined, fallback: number): number => {
    for (const raw of [flag, env]) {
      if (raw === undefined || raw === null || raw === "") continue;
      const value = Number(raw);
      if (!Number.isFinite(value) || value <= 0) throw new Error(`Invalid continuation budget '${String(raw)}': expected a positive number.`);
      return value;
    }
    return fallback;
  };
  return {
    ...DEFAULT_CONTINUATION,
    maxTotalSteps: Math.floor(positive(options.maxTotalSteps, process.env.NEXUS_MAX_TOTAL_STEPS, DEFAULT_CONTINUATION.maxTotalSteps)),
    maxTurnMinutes: positive(options.maxTurnMinutes, process.env.NEXUS_MAX_TURN_MINUTES, DEFAULT_CONTINUATION.maxTurnMinutes),
    stagnationSteps: Math.floor(positive(options.stagnationSteps, process.env.NEXUS_STAGNATION_STEPS, DEFAULT_CONTINUATION.stagnationSteps)),
  };
}

/** Replaces the "local-model" placeholder with the first model the gateway lists; unchanged if the gateway is unreachable. */
export async function autoDetectModel(config: HarnessConfig): Promise<HarnessConfig> {
  // A provider's catalog lists billable models; one is never chosen on the operator's behalf.
  if (config.provider || config.model !== "local-model") return config;
  try {
    const models = await new LocalLlmClient(config).listModels();
    if (models.length > 0) return { ...config, model: models[0] };
  } catch {
    // Keep the placeholder; the first inference request will surface the connection problem.
  }
  return config;
}
