          submit: (s) => this.submitGuardingLength(lengthGuard, this.messages, (request) =>
            activeClient.chatCompletion(request, [...HARNESS_TOOLS, READ_FINDINGS_CAPABILITY.toolDefinition as ToolDefinition], s.requestId, signal)),
