4387:  private buildTurnResult(input: {
    if (input.interruption) {
      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "INTERRUPTED", outcome: "NOT_ESTABLISHED", reason: "OPERATOR_INTERRUPT", finalOutputComplete: false,
      }));
    }
    if (input.inferenceFailure) {
      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "FAILED", outcome: "NOT_ESTABLISHED", reason: "INFERENCE_FAILED",
        detail: `${input.inferenceFailure.kind}/${input.inferenceFailure.origin}${input.inferenceFailure.httpStatus ? ` HTTP ${input.inferenceFailure.httpStatus}` : ""}` +
          (lastRecovery?.state === "EXHAUSTED" ? `; provider recovery exhausted after ${lastRecovery.submissions.length} submissions, ${Math.round(lastRecovery.waitedMs / 1000)}s waiting` : ""),
        finalOutputComplete: false,
      }));
    }
    if (input.capacityBlock) {
      const c = input.capacityBlock;
      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "BLOCKED", outcome: "NOT_ESTABLISHED", reason: "CONTEXT_CAPACITY_EXCEEDED",
        detail: `${c.estimatedPromptTokens}+${c.completionReserveTokens}+${c.toolResponseReserveTokens}>${c.contextLimit}`,
        finalOutputComplete: false, capacity: c,
      }));
    }
    if (input.limitReached) {
      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "LIMIT_REACHED", outcome: "NOT_ESTABLISHED", reason: input.stopReason ?? "STEP_LIMIT_REACHED",
        ...(input.stopDetail ? { detail: input.stopDetail } : {}), finalOutputComplete: false,
      }));
    }
    // A finished turn with operator requirements still open or blocked established nothing about the objective, whatever
    // the verifier said about the code (a failing verifier is the more specific reason and is reported below).
    const requirementsIncomplete = open.length > 0 || blocked.length > 0;
    const incompleteDetail = () =>
      [open.length ? `open: ${open.map((r) => r.id).join(", ")}` : "", blocked.length ? `blocked: ${blocked.map((r) => `${r.id} (${r.note ?? "no reason"})`).join(", ")}` : ""]
        .filter(Boolean)
        .join("; ")
        .slice(0, 300);

    // Execution COMPLETED: derive the engineering outcome strictly from verifier evidence.
    if (this.hasPendingModifications) {
      if (evidence?.status === "FAILED") {
        return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "NOT_ESTABLISHED", reason: "VERIFIER_FAILED", detail: evidence.command }));
      }
      if (evidence?.status === "TIMED_OUT") {
        return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "NOT_ESTABLISHED", reason: "VERIFIER_TIMED_OUT", detail: `${evidence.command} (deadline ${evidence.deadlineSecs}s)` }));
      }
      if (requirementsIncomplete) {
        return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "NOT_ESTABLISHED", reason: "REQUIREMENTS_INCOMPLETE", detail: incompleteDetail() }));
      }
      const noVerifier = evidence?.status === "NO_APPLICABLE_VERIFIER" ||
        (!evidence && !this.config.authoritativeVerifierCommand?.trim() && !discoverVerifier(this.config.workspace));
      return deepFreezeTurn(assertTurnResultInvariants({
        ...base, execution: "COMPLETED", outcome: "UNVERIFIED",
        reason: noVerifier ? "NO_APPLICABLE_VERIFIER" : "VERIFICATION_NOT_RUN",
      }));
    }
    if (requirementsIncomplete) {
      return deepFreezeTurn(assertTurnResultInvariants({ ...base, execution: "COMPLETED", outcome: "NOT_ESTABLISHED", reason: "REQUIREMENTS_INCOMPLETE", detail: incompleteDetail() }));
    }
    if (this.turnMutations > 0 || this.turnCarriedChanges) {
      if (evidence?.status === "PASSED") {
        // The verifier passed on the change; it does not show the change's content rests on what the model saw. Output
        // that left context during the turn and was not read again is counted on the result (CTX-03).
        const contextQualifier = this.turnRemovedObservations.size ? { contextNotRetained: this.turnRemovedObservations.size } : {};
        if (evidence.isDeliverableBound === false) {
          return deepFreezeTurn(assertTurnResultInvariants({
            ...base,
            ...contextQualifier,
            execution: "COMPLETED",
            outcome: "REGRESSION_FREE",
            reason: "REGRESSION_FREE",
            detail: "Passing test run did not cover the modified deliverables.",
          }));
        }
        if (evidence.source !== "configured" && evidence.independent !== true) {
          return deepFreezeTurn(assertTurnResultInvariants({
            ...base,
            ...contextQualifier,
            execution: "COMPLETED",
            outcome: "REGRESSION_FREE",
            reason: "REGRESSION_FREE",
            detail: `Tests pass, but ${evidence.independenceDetail ?? "nothing independent of Nexus shows the change"}.`,
          }));
        }
        return deepFreezeTurn(assertTurnResultInvariants({ ...base, ...contextQualifier, execution: "COMPLETED", outcome: "VERIFIED" }));

/** True only for work the operator can treat as finished without further evidence. */
export function turnSucceeded(t: TurnResult): boolean {
  return exitCodeForTurn(t) === 0;
}

/** Durable task lifecycle status derived from the execution dimension only. */
export function lifecycleStatusForTurn(t: TurnResult): "completed" | "failed" | "interrupted" {
  if (t.execution === "INTERRUPTED") return "interrupted";
  if (t.execution === "COMPLETED") return "completed";
  return "failed";
}

/** Single-line projection used by terminal surfaces. Presentation only; semantics live in the fields. */
/** The context qualifier of a verified result, for its summary line. */
function contextTail(t: TurnResult): string {
  const n = t.contextNotRetained;
  return n ? `; ${n} tool output${n === 1 ? "" : "s"} it may rest on left context and ${n === 1 ? "was" : "were"} not read again` : "";
}

export function summarizeTurn(t: TurnResult): { heading: string; line: string } {
  const exec = t.execution;
  const tail = t.reason ? ` (${t.reason}${t.detail ? `: ${t.detail}` : ""})` : "";
  if (exec === "INTERRUPTED") {
    const i = t.interruption;
    const extra = i?.outstandingTool ? ` - ${i.outstandingTool} ${i.outstandingToolSettled ? "settled" : "still settling"}` : "";
    return { heading: "TURN INTERRUPTED", line: `execution=INTERRUPTED outcome=NOT_ESTABLISHED${extra}; ${i?.undispatchedToolCalls ?? 0} tool call(s) not dispatched` };
  }
  if (exec === "FAILED") return { heading: "TURN FAILED", line: `execution=FAILED outcome=NOT_ESTABLISHED${tail}` };
  if (exec === "BLOCKED" && t.capacity) {
    const c = t.capacity;
    const fate = c.pendingMessageRetained ? "your message and the conversation so far are kept" : "your message was not added to the conversation";
    return {
      heading: "TURN BLOCKED - CONTEXT FULL",
      line: `execution=BLOCKED outcome=NOT_ESTABLISHED (CONTEXT_CAPACITY_EXCEEDED: ${c.estimatedPromptTokens} prompt + ${c.completionReserveTokens} completion + ${c.toolResponseReserveTokens} tool reserve > ${c.contextLimit} limit). ` +
        `${c.modelCalled ? "No further request was sent" : "No request was sent"}; ${fate}. ` +
        `Raise --context-limit, run /clear, or ask for something narrower; /compact may not help if one retained result is itself too large.`,
    };
  }
  if (exec === "BLOCKED") return { heading: "TURN BLOCKED", line: `execution=BLOCKED outcome=NOT_ESTABLISHED${tail}` };
  if (exec === "LIMIT_REACHED") {
    const c = t.continuation;
    const segments = c && c.segments > 1 ? ` across ${c.segments} segments of ${c.segmentSteps}` : "";
    if (t.reason === "STAGNATION_DETECTED") {
      return { heading: "STOPPED - NO PROGRESS", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (STAGNATION_DETECTED${t.detail ? `: ${t.detail}` : ""}; ${t.steps.used} steps${segments})` };
    }
    if (t.reason === "TIME_BUDGET_EXHAUSTED") {
      return { heading: "TIME BUDGET EXHAUSTED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (TIME_BUDGET_EXHAUSTED${t.detail ? `: ${t.detail}` : ""}; ${t.steps.used} steps${segments})` };
    }
    if (t.reason === "STEP_BUDGET_EXHAUSTED") {
      return { heading: "STEP BUDGET EXHAUSTED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (${t.steps.used}/${t.steps.max} steps${segments}; raise --max-total-steps to allow more)` };
    }
    return { heading: "STEP LIMIT REACHED", line: `execution=LIMIT_REACHED outcome=NOT_ESTABLISHED (${t.steps.used}/${t.steps.max} steps)` };
  }
  switch (t.outcome) {
    case "VERIFIED":
      return { heading: "TASK COMPLETED - VERIFIED", line: `execution=COMPLETED outcome=VERIFIED (${t.verification?.command})${contextTail(t)}` };
    case "REGRESSION_FREE":
      return { heading: "TASK COMPLETED - REGRESSION FREE", line: `execution=COMPLETED outcome=REGRESSION_FREE (${t.verification?.command})${tail}${contextTail(t)}` };
    case "NOT_REQUIRED":
      return { heading: "TURN ENDED - NO CHANGES TO VERIFY", line: `execution=COMPLETED outcome=NOT_REQUIRED modelStop=${t.modelStop}` };
    case "UNVERIFIED":
      return { heading: "TURN ENDED - UNVERIFIED", line: `execution=COMPLETED outcome=UNVERIFIED${tail}` };
    default:
      if (t.reason === "REQUIREMENTS_INCOMPLETE") {
        return { heading: "TURN ENDED - REQUIREMENTS OPEN", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
      }
      return { heading: "TURN ENDED - NOT ESTABLISHED", line: `execution=COMPLETED outcome=NOT_ESTABLISHED${tail}` };
  }
}

/** Result for a turn that ended by an exception outside the model/tool protocol (never a success). */
export function failedTurnFromError(err: unknown, maxSteps: number): TurnResult {
  const message = err instanceof Error ? err.message : String(err);
  return deepFreezeTurn(assertTurnResultInvariants({
    execution: "FAILED",
    outcome: "NOT_ESTABLISHED",
    acceptance: "NOT_REQUESTED",
    reason: "UNHANDLED_ERROR",
    detail: message.slice(0, 300),
    modelStop: "NONE",
    finalOutputComplete: false,
    verification: null,
    interruption: null,
    inferenceFailure: null,
    steps: { used: 0, max: maxSteps, limitReached: false },
    unverifiedChangesPending: false,
    finishedAt: new Date().toISOString(),
  }));
}
