      const written = (body.messages as any[]).filter((m) => m.role === "tool").length;
      return written < 20 ? write(`s/s${written + 1}.txt`) : { kind: "tools", calls: [{ name: "task_completed", args: { summary: "wrote 20 files" } }] };
    });
