describe("C. persistence failures are truthful", () => {
  test("an archive failure leaves the conversation uncompacted and says so", { timeout: 60_000 }, async () => {
    const repo = makeRepo();
    const gw = await startGateway((n) => (n <= 3 ? write(`x${n}.txt`) : text("done")));
