"""In-memory store of items keyed by SKU."""
from typing import Dict, List, Optional
from .models import Item


class Store:
    """Holds items by SKU."""

    def __init__(self) -> None:
        self._items: Dict[str, Item] = {}

    def add(self, item: Item) -> None:
        """Add a new item; a duplicate SKU raises KeyError."""
        if item.sku in self._items:
            raise KeyError(f"duplicate sku {item.sku}")
        self._items[item.sku] = item

    def remove(self, sku: str) -> Item:
        """Remove and return an item; an unknown SKU raises KeyError."""
        return self._items.pop(sku)

    def find(self, sku: str) -> Optional[Item]:
        """The item with this SKU, or None."""
        return self._items.get(sku)

    def items(self) -> List[Item]:
        """All items in insertion order."""
        return list(self._items.values())

    def total_value_cents(self) -> int:
        """Sum of item values in cents."""
        return sum(i.value_cents() for i in self._items.values())
