export interface WorkspaceStateIdentityOptions {
  includeIndexState?: boolean;
  relevantInputs?: string[];
}

/**
 * Establishes content-based workspace candidate identity.
 * Recomputes fresh workspace inputs from disk and git status on every invocation.
 * Detects intervening edits, Git index staging changes, dependencies, and relevant inputs.
 * If candidate identity cannot be reliably established, reports uncertainty honestly.
 */
export function establishWorkspaceStateIdentity(
  workspaceRoot: string,
  candidateTracker?: CandidateTracker,
  options: WorkspaceStateIdentityOptions = {}
): WorkspaceStateIdentity {
  const tracker = candidateTracker || new CandidateTracker();
  try {
    const identity = tracker.computeCandidateIdentitySync(workspaceRoot);
    let indexDigest = "";
    if (options.includeIndexState !== false && identity.isGit) {
      try {
        const status = execFileSync("git", ["status", "--porcelain=v1"], {
          cwd: workspaceRoot,
          encoding: "utf-8",
          stdio: ["ignore", "pipe", "ignore"],
        });
        indexDigest = createHash("sha256").update(status).digest("hex").slice(0, 12);
      } catch {}
    }

    let inputsDigest = "";
    if (options.relevantInputs && options.relevantInputs.length > 0) {
      const parts: string[] = [];
      for (const rel of options.relevantInputs.slice().sort()) {
        const full = path.join(workspaceRoot, rel);
        try {
          if (fs.existsSync(full)) {
            parts.push(`${rel}:${createHash("sha256").update(fs.readFileSync(full)).digest("hex")}`);
          }
        } catch {}
      }
      if (parts.length > 0) {
        inputsDigest = createHash("sha256").update(parts.join("\n")).digest("hex").slice(0, 12);
      }
    }

    const stateParts = [`cand:${identity.candidateId}`];
    if (indexDigest) stateParts.push(`idx:${indexDigest}`);
    if (inputsDigest) stateParts.push(`inp:${inputsDigest}`);

