export function buildActionObservation(
  toolName: string,
  args: unknown,
  outcome: { success: boolean; output?: string; error?: string },
  workspaceRoot: string,
  candidateTracker?: CandidateTracker
): ActionObservation {
  const normalizedArgs = normalizeToolArguments(args, workspaceRoot);
  const actionKey = `${toolName}\u0000${normalizedArgs}`;
