/**
 * Recognizes polling operations (checking status, waiting on asynchronous tasks).
 */
export function isPollingOperation(toolName: string, args: unknown): boolean {
  const lower = toolName.toLowerCase();
  if (lower.includes("status") || lower.includes("poll") || lower.includes("manage_task")) {
    return true;
  }
