-import { ChatMessage, ToolDefinition, HarnessConfig, ToolCall } from "./types.js";
+import { ChatMessage, ToolDefinition, HarnessConfig, ToolCall, TokenCountSource } from "./types.js";
+export interface DiscoveredProviderCapabilities {
+  modelId: string;
+  contextLength?: number;
+  maxCompletionTokens?: number;
+  limitsVersion?: string;
+  reasoning?: { budget?: number; mode?: string };
+  serving?: any[];
+  refreshedAt: string;
+}
+
+export interface RemoteTokenCountResult {
+  promptTokens: number;
+  source: TokenCountSource;
+  contextLength?: number;
+  limitsVersion?: string;
+  workerId?: string;
+}
+
+  private discoveredCapabilities?: DiscoveredProviderCapabilities;
+  public getDiscoveredCapabilities(): DiscoveredProviderCapabilities | undefined {
+    return this.discoveredCapabilities;
+  }
+
+  public setDiscoveredCapabilities(caps: DiscoveredProviderCapabilities | undefined): void {
+    this.discoveredCapabilities = caps;
+  }
+
+  /**
+   * Discovers provider capabilities dynamically from /models when supported.
+   * Caches context_length, max_completion_tokens, limits_version, reasoning, and serving pool details.
+   */
+  public async discoverCapabilities(modelName?: string): Promise<DiscoveredProviderCapabilities | undefined> {
+    const targetModel = modelName || this.model;
+    const url = this.endpoint;
+    const origin = originOf(url);
+    if (!origin) return undefined;
+
+    const base = url.endsWith("/v1") ? url : `${url.replace(/\/+$/, "")}/v1`;
+    const modelsUrl = `${base}/models`;
+
+    try {
+      const controller = new AbortController();
+      const timer = setTimeout(() => controller.abort(), 4000);
+      const res = await fetch(modelsUrl, {
+        method: "GET",
+        headers: {
+          ...this.authorization(url),
+          Accept: "application/json",
+        },
+        signal: controller.signal,
+        ...this.fetchPolicy(),
+      });
+      clearTimeout(timer);
+
+      if (!res.ok) return undefined;
+      const data = (await res.json()) as any;
+      const list: any[] = Array.isArray(data?.data) ? data.data : Array.isArray(data?.models) ? data.models : [];
+      const entry = list.find((m) => m?.id === targetModel || m?.name === targetModel);
+      if (entry) {
+        const contextLength = entry.context_length ?? entry.max_model_len ?? entry.context_window;
+        const maxCompletionTokens = entry.max_completion_tokens ?? entry.max_tokens;
+        const limitsVersion = entry.limits_version;
+        const reasoning = entry.reasoning;
+        const serving = entry.serving;
+        this.discoveredCapabilities = {
+          modelId: targetModel,
+          contextLength: typeof contextLength === "number" && contextLength > 0 ? contextLength : undefined,
+          maxCompletionTokens: typeof maxCompletionTokens === "number" && maxCompletionTokens > 0 ? maxCompletionTokens : undefined,
+          limitsVersion: typeof limitsVersion === "string" ? limitsVersion : undefined,
+          reasoning,
+          serving,
+          refreshedAt: new Date().toISOString(),
+        };
+        return this.discoveredCapabilities;
+      }
+    } catch {
+      // Endpoint does not support /models or request failed; cleanly fall back
+    }
+    return undefined;
+  }
+
+  /**
+   * Queries remote /v1/tokenize endpoint when available.
+   * Truthfully marks token count from a sampled worker as 'exact_sampled_worker' rather than
+   * claiming it is guaranteed for the admitted inference execution across distributed pools.
+   */
+  public async countTokensRemote(
+    messages: ChatMessage[],
+    tools: ToolDefinition[],
+    modelName?: string
+  ): Promise<RemoteTokenCountResult | undefined> {
+    const targetModel = modelName || this.model;
+    const url = this.endpoint;
+    const origin = originOf(url);
+    if (!origin) return undefined;
+
+    const base = url.endsWith("/v1") ? url : `${url.replace(/\/+$/, "")}/v1`;
+    const tokenizeUrl = `${base}/tokenize`;
+
+    try {
+      const controller = new AbortController();
+      const timer = setTimeout(() => controller.abort(), 6000);
+      const res = await fetch(tokenizeUrl, {
+        method: "POST",
+        headers: {
+          ...this.authorization(url),
+          "Content-Type": "application/json",
+          Accept: "application/json",
+        },
+        body: JSON.stringify({
+          model: targetModel,
+          messages,
+          tools: tools.length > 0 ? tools : undefined,
+        }),
+        signal: controller.signal,
+        ...this.fetchPolicy(),
+      });
+      clearTimeout(timer);
+
+      if (!res.ok) return undefined;
+      const data = (await res.json()) as any;
+      if (typeof data?.prompt_tokens === "number") {
+        const source: TokenCountSource = data.source === "exact" ? "exact_sampled_worker" : "estimated_conservative";
+        return {
+          promptTokens: data.prompt_tokens,
+          source,
+          contextLength: data.context_length,
+          limitsVersion: data.limits_version,
+          workerId: data.worker_id,
+        };
+      }
+    } catch {
+      // Remote tokenize endpoint unavailable; caller falls back safely
+    }
+    return undefined;
+  }
+

