+export function createExecutionContinuity(): ExecutionContinuityState {
+  return {
+    cumulativeSteps: 0,
+    stepsWithoutProgress: 0,
+    stagnationEvents: 0,
+    recoveriesUsed: 0,
+    observations: [],
+    failedApproaches: [],
+    recoveryInterventions: [],
+    progressEvidence: [],
+  };
+}
+
+/**
+ * Loop-preserving bounded observation tracking.
+ * Entries with count >= 2 represent demonstrated or potential loops and are protected from eviction.
+ * When the list exceeds capacity, entries with count === 1 are evicted first (oldest lastSeenStep first).
+ * Only when all entries have count >= 2 does eviction prune the oldest repeated entry.
+ */
+export function recordContinuityObservation(
+  continuity: ExecutionContinuityState,
+  key: string,
+  step: number
+): number {
+  const existing = continuity.observations.find((o) => o.key === key);
+  if (existing) {
+    existing.count++;
+    existing.lastSeenStep = step;
+    return existing.count;
+  }
+
+  if (continuity.observations.length >= MAX_CONTINUITY_OBSERVATIONS) {
+    const singleIndex = continuity.observations.findIndex((o) => o.count === 1);
+    if (singleIndex >= 0) {
+      continuity.observations.splice(singleIndex, 1);
+    } else {
+      let bestEvictIdx = 0;
+      for (let i = 1; i < continuity.observations.length; i++) {
+        const cur = continuity.observations[i];
+        const best = continuity.observations[bestEvictIdx];
+        if (cur.count < best.count || (cur.count === best.count && cur.lastSeenStep < best.lastSeenStep)) {
+          bestEvictIdx = i;
+        }
+      }
+      continuity.observations.splice(bestEvictIdx, 1);
+    }
+  }
+
+  continuity.observations.push({
+    key,
+    count: 1,
+    firstSeenStep: step,
+    lastSeenStep: step,
+  });
+  return 1;
+}
